    public void spreadNether(){
        if (this.level instanceof ServerLevel serverLevel) {
            int activeHeretics = this.level.getEntitiesOfClass(Mob.class, this.getBoundingBox().inflate(10.0D), living -> living.isAlive() && living instanceof IHeretic heretic && heretic.isCasting() && heretic.getMonolith() == this).size();
            Vec3 skyVec = new Vec3(this.getX(), this.getY() + this.cloudHeight, this.getZ());
            if (!this.level.canSeeSky(this.blockPosition().above())) {
                skyVec = this.level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING, this.blockPosition()).getCenter().add(0, this.cloudHeight, 0);
            }
            if (this.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING) && MobsConfig.ObsidianMonolithSpread.get() && this.level.dimension() != Level.NETHER) {
                if (this.startSpreading()) {
                    if (this.level.isEmptyBlock(BlockPos.containing(skyVec))) {
                        ServerParticleUtil.addAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 2.0F);
                        ServerParticleUtil.addReverseAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 6.0F);
                        ServerParticleUtil.addAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, 10.0F);
                    }
                    this.netherSpreaderUtil.updateCursors(this.level, this.blockPosition().below(), this.random, true);

                    if (this.getSpreaderLeveling() >= 100) {
                        this.setSpreaderLeveling(0);
                        if (this.getSpreaderLevel() < 9) {
                            this.setSpreaderLevel(this.getSpreaderLevel() + 1);
                        }
                    }

                    if (this.getSpreaderProgress() >= 1.0F) {
                        this.setSpreaderProgress(0.0F);
                        this.setSpreaderLeveling(this.getSpreaderLeveling() + 1);
                        this.netherSpreaderUtil.clear();
                        for (int i = 0; i < 5; i++) {
                            int range = this.getSpreaderLevel();
                            BlockPos blockPos = this.blockPosition().below();
                            if (range > 0) {
                                int x = serverLevel.getRandom().nextInt(-range, range);
                                int y = serverLevel.getRandom().nextInt(-range, range / 2);
                                int z = serverLevel.getRandom().nextInt(-range, range);
                                blockPos = this.blockPosition().below().offset(x, y, z);
                            }
                            this.netherSpreaderUtil.addCursors(blockPos, 10);
                        }
                    } else {
                        this.setSpreaderProgress(this.getSpreaderProgress() + (0.005F * (activeHeretics + 1)));
                    }
                } else {
                    ++this.startUp;
                    if (this.startUp > 0) {
                        if (this.level.isEmptyBlock(BlockPos.containing(skyVec))) {
                            float radius = 4.0F;
                            float totalTime = MathHelper.minecraftDayToTicks(MobsConfig.ObsidianMonolithStartUpTime.get());
                            if (this.startUp > totalTime / 4.0F) {
                                radius = 6.0F;
                            }
                            if (this.startUp > totalTime / 2.0F) {
                                radius = 8.0F;
                            }
                            if (this.startUp > totalTime / 1.5F) {
                                radius = 12.0F;
                            }
                            ServerParticleUtil.addReverseVisualAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, radius / 2.0F);
                            ServerParticleUtil.addVisibleAuraParticles(serverLevel, ModParticleTypes.SPELL_CLOUD.get(), skyVec, radius);
                        }
                    }
                }
            }
        }
    }

