                p_41182_.getItemInHand().shrink(1);
                serverLevel.playSound(null, blockPos.getX(), blockPos.getY(), blockPos.getZ(), ModSounds.VOID_FRAME_UNLOCK.get(), SoundSource.BLOCKS, 2.0F, 1.0F);
                Vec3 vec3 = blockPos.above().getCenter();
